// Generates supabase/seed.sql from the shared sample catalogue so the
// database and the prototype always show the same placeholder content.
// Run: pnpm db:seed:generate
import { writeFileSync } from "node:fs";
import { creators, instructors, workouts } from "../packages/mock-data/src/index";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const arr = (a: string[]) => `'{${a.map((x) => `"${x}"`).join(",")}}'`;
const lines: string[] = [
  "-- SAMPLE DATA ONLY — invented placeholder creators, instructors and workouts.",
  "-- Generated by scripts/generate-seed.ts. Safe to re-run (upserts on stable keys).",
];

for (const c of creators) {
  const minor = c.isMinor;
  lines.push(
    `insert into public.creators (display_name, legal_name, country, is_minor, guardian_managed, status, referral_code) values (${q(c.displayName)}, ${q(c.legalName)}, 'AU', ${minor}, ${minor}, ${q(c.status)}, ${q(c.referralCode)}) on conflict (referral_code) do update set display_name = excluded.display_name, status = excluded.status;`,
  );
}
const creatorRef = (id: string) => `(select id from public.creators where referral_code = ${q(creators.find((c) => c.id === id)!.referralCode)})`;

for (const i of instructors) {
  lines.push(
    `insert into public.instructors (creator_id, display_name, bio, is_minor, specialties, accent) select ${creatorRef(i.creatorId)}, ${q(i.displayName)}, ${q(i.bio)}, ${i.isMinor}, ${arr(i.specialties)}, ${q(i.accent)} where not exists (select 1 from public.instructors where display_name = ${q(i.displayName)});`,
  );
}
const instructorRef = (id: string) => `(select id from public.instructors where display_name = ${q(instructors.find((x) => x.id === id)!.displayName)})`;

for (const w of workouts) {
  const ins = instructors.find((x) => x.id === w.instructorId)!;
  const consent = w.rights.guardianConsent === "not-applicable" ? "null" : String(w.rights.guardianConsent);
  lines.push(
    `insert into public.workouts (slug, title, description, instructor_id, creator_id, category, duration_sec, intensity, equipment, age_bands, captions, accessibility_notes, state, published_at, rights_creator_licence_signed, rights_music_cleared, rights_safety_reviewed, rights_guardian_consent, territories, thumbnail) values (${q(w.id.replace(/^wk-/, ""))}, ${q(w.title)}, ${q(w.description)}, ${instructorRef(w.instructorId)}, ${creatorRef(ins.creatorId)}, ${q(w.category)}, ${w.durationSec}, ${q(w.intensity)}, ${arr(w.equipment)}, ${arr(w.ageBands)}, ${w.captions}, ${w.accessibilityNotes ? q(w.accessibilityNotes) : "null"}, ${q(w.state)}, ${w.publishedAt ? q(w.publishedAt + "T09:00:00+10:00") : "null"}, ${w.rights.creatorLicenceSigned}, ${w.rights.musicCleared}, ${w.rights.safetyReviewed}, ${consent}, ${arr(w.rights.territories)}, ${q(JSON.stringify(w.thumbnail))}::jsonb) on conflict (slug) do nothing;`,
  );
}
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n") + "\n");
console.log(`seed.sql: ${creators.length} creators, ${instructors.length} instructors, ${workouts.length} workouts`);
